/* ON Mission 16.7.0 — Market Launch Workbench UI. One governed surface for market package intake, readiness and release. */
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v:[];
const tone=s=>['LIVE','READY','VALIDATED','AUTHORIZED','PUBLISHED','VERIFIED'].includes(String(s||'').toUpperCase())?'ok':['REJECTED','SUSPENDED','RETIRED'].includes(String(s||'').toUpperCase())?'bad':'warn';
const pill=s=>`<span class="pill ${tone(s)}">${esc(String(s||'UNKNOWN').toUpperCase())}</span>`;
const jsonPretty=v=>JSON.stringify(v??{},null,2);const safeEvidenceUrl=v=>{try{const u=new URL(String(v||''));return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const governedHeaders={'X-ONM-Explicit-Governed-Action':'1'};
const commonResourceFields={
  country:[['name','Country name','text',true],['isoCode','ISO 3166-1 alpha-2 code','text',true],['defaultLanguage','Default language code','text',false]],
  language:[['name','Language name','text',true],['code','Language code (BCP 47 / ISO) ','text',true],['nativeName','Native name','text',false]],
  sector:[['name','Sector name','text',true],['code','Stable sector code','text',true],['description','Description','textarea',false]],
  consent:[['name','Consent title','text',true],['code','Stable consent code','text',true],['language','Language code','text',true],['message','Consent message','textarea',true]],
  role:[['name','Role name','text',true],['code','Stable role code','text',true],['description','Description','textarea',false]],
  subscription_plan:[['name','Plan name','text',true],['code','Stable plan code','text',true],['currency','Currency (ISO 4217)','text',true],['price','Price','number',true],['billingPeriod','Billing period','select',true,['monthly','yearly','one_time']]],
  eligibility_policy:[['name','Policy name','text',true],['code','Stable policy code','text',true],['description','Policy description','textarea',true]],
  product:[['name','Product name','text',true],['code','Stable product code','text',true],['description','Description','textarea',false]]
};
const resourceTypeKey=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
function typedResourceFields(entryType,definition={}){const key=resourceTypeKey(entryType);const schema=definition.schema||definition.jsonSchema||definition.payloadSchema||{};const props=schema.properties&&typeof schema.properties==='object'?schema.properties:null;const required=new Set(Array.isArray(schema.required)?schema.required:[]);if(props){return Object.entries(props).slice(0,30).map(([name,field])=>({name,label:field.title||field.label||name,type:field.enum?'select':field.type==='boolean'?'checkbox':field.type==='number'||field.type==='integer'?'number':field.type==='object'||field.type==='array'?'json':field.format==='textarea'?'textarea':'text',required:required.has(name),options:field.enum||[]}));}return (commonResourceFields[key]||[]).map(([name,label,type,required,options])=>({name,label,type,required,options:options||[]}));}
function renderTypedResourceFields(entryType,definition={}){const fields=typedResourceFields(entryType,definition);if(!fields.length)return '<div class="notice">This resource type has no supported typed form yet. Use the advanced JSON editor; the canonical authority remains responsible for validation.</div>';return fields.map(f=>{const name=esc(f.name),label=esc(f.label);if(f.type==='select')return `<label class="mf-field"><span>${label}${f.required?' *':''}</span><select class="input" data-mf-resource-field="${name}" ${f.required?'required':''}><option value="">Select…</option>${arr(f.options).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;if(f.type==='checkbox')return `<label class="mf-field"><input type="checkbox" data-mf-resource-field="${name}"> ${label}</label>`;if(f.type==='textarea'||f.type==='json')return `<label class="mf-field"><span>${label}${f.required?' *':''}</span><textarea class="input" data-mf-resource-field="${name}" rows="3" ${f.required?'required':''} ${f.type==='json'?'data-json-field="true"':''}></textarea></label>`;return `<label class="mf-field"><span>${label}${f.required?' *':''}</span><input class="input" type="${f.type==='number'?'number':'text'}" data-mf-resource-field="${name}" ${f.required?'required':''} ${f.type==='number'?'step="any"':''}></label>`;}).join('');}
function readTypedResourceFields(panel){const payload={};for(const field of panel.querySelectorAll('[data-mf-resource-field]')){const key=field.dataset.mfResourceField;if(field.type==='checkbox'){payload[key]=field.checked;continue;}const value=field.value.trim();if(value==='')continue;if(field.dataset.jsonField==='true'){try{payload[key]=JSON.parse(value);}catch{throw new Error(`${key} must contain valid JSON.`);}continue;}if(field.type==='number')payload[key]=Number(value);else payload[key]=value;}return payload;}
const mutation=(clientApi,path,body={})=>clientApi(path,{method:'POST',headers:governedHeaders,body});
const withError=async(fn)=>{try{return await fn()}catch(e){alert(`${e?.code||'MARKET_FACTORY_ACTION_FAILED'}: ${e?.message||'Market Factory action failed. No success was assumed.'}`);return null}};
function readinessCard(v){const r=v?.readiness_json||{};const blockers=arr(r.blockers),warnings=arr(r.warnings),validated=Object.prototype.hasOwnProperty.call(r,'valid');return `<section class="card section mf-readiness"><header class="section-head"><div><span class="eyebrow">MARKET READINESS</span><h2>${Number(r.score||0)}%</h2><p class="sub">${validated?'Publish remains blocked until mandatory gates pass.':'Run validation after reviewing package data and task evidence.'}</p></div>${pill(!validated?'NOT VALIDATED':r.valid?'READY':'BLOCKED')}</header><div class="mf-progress"><span style="width:${Math.max(0,Math.min(100,Number(r.score||0)))}%"></span></div><div class="mf-gates"><div><b>${blockers.length}</b><small>blockers</small></div><div><b>${warnings.length}</b><small>warnings</small></div><div><b>${arr(v?.dependency_snapshot_json?.missing).length}</b><small>dependency issues</small></div></div>${blockers.length?`<div class="notice danger"><b>BLOCKERS</b><ul>${blockers.map(x=>`<li>${esc(x.message||x.code||x)}</li>`).join('')}</ul></div>`:''}${warnings.length?`<div class="notice"><b>WARNINGS / REPLACEMENT PLAN</b><ul>${warnings.map(x=>`<li>${esc(x.message||x.code||x)}</li>`).join('')}</ul></div>`:''}</section>`;}
function reconciliationCard(p){if(!p)return '';const op=p.operations||[];const issues=p.issues||[];const counts=p.issueSummary||{};return `<section class="card section"><header class="section-head"><div><span class="eyebrow">READINESS RECONCILIATION · READ ONLY</span><h2>${p.safeToApply?'No canonical conflicts detected':'Canonical conflicts require resolution'}</h2><p class="sub">${p.summary?.create||0} create · ${p.summary?.reuse||0} reuse · ${p.summary?.update||0} change-review · ${p.summary?.conflicts||0} conflicts</p><p class="mini">${counts.BLOCKED||0} blocked · ${counts.REQUIRES_GOVERNED_CREATE||0} require governed creation · ${counts.HUMAN_REVIEW_REQUIRED||0} require human review</p></div>${pill(p.safeToApply?'NO CONFLICTS':'BLOCKED')}</header>${(p.conflicts||[]).length?`<div class="notice danger"><b>CONFLICTS</b><ul>${p.conflicts.map(x=>`<li>${esc(x.message)}</li>`).join('')}</ul></div>`:''}${issues.length?`<h3>Issues and next governed steps</h3><div class="table-wrap"><table class="table"><thead><tr><th>State</th><th>Issue</th><th>Owning authority</th><th>Next step</th></tr></thead><tbody>${issues.map(x=>`<tr><td>${pill(x.state)}</td><td><b>${esc(x.category)}</b><br><code>${esc(x.identity)}</code><p class="mini">${esc(x.message)}</p></td><td>${esc(x.owner)}</td><td>${esc(x.nextStep)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">No missing canonical identities or conflicts were detected in the package scope. This is not a runtime or launch certification.</div>'}<details class="mf-package"><summary>ADVANCED · CANONICAL VALUE COMPARISON</summary><div class="table-wrap"><table class="table"><thead><tr><th>Domain</th><th>Canonical identity</th><th>Operation</th><th>Current → resulting value</th><th>Requested by package</th></tr></thead><tbody>${op.map(x=>`<tr><td>${esc(x.domain)}</td><td><code>${esc(x.identity)}</code></td><td>${pill(x.operation)}</td><td><small>${esc(JSON.stringify(x.current??null))} → ${esc(JSON.stringify(x.proposed??null))}</small></td><td><small>${esc(JSON.stringify(x.requested??x.proposed??null))}</small></td></tr>`).join('')}</tbody></table></div></details><p class="mini">Read-only preview generated ${esc(p.generatedAt)}. No canonical records were changed. This report covers package-to-canonical reconciliation only; legal approval, runtime health, billing and customer journey require their own evidence.</p></section>`;}
function versionActions(v){const id=Number(v?.id||0);const s=String(v?.status||'').toUpperCase();return `<div class="actions">${s==='DRAFT'?`<button class="btn primary" data-mf-validate="${id}">VALIDATE</button>`:''}${s==='VALIDATED'?`<button class="btn primary" data-mf-authorize="${id}">AUTHORIZE / SIGN</button>`:''}${s==='AUTHORIZED'?`<button class="btn primary" data-mf-publish="${id}">PUBLISH MARKET</button>`:''}${s==='PUBLISHED'?`<button class="btn primary" data-mf-verify="${id}">VERIFY RELEASE</button>`:''}${s==='VERIFIED'?`<button class="btn primary" data-mf-activate="${id}">ACTIVATE MARKET</button>`:''}${s==='LIVE'?`<button class="btn muted" data-mf-export="${id}">EXPORT PACKAGE</button>`:''}${['LIVE','SUSPENDED','RETIRED','RESTRICTED'].includes(s)?`<button class="btn muted" data-mf-export="${id}">EXPORT PACKAGE</button>`:''}</div>`;}
function versionRow(v){return `<tr data-mf-select-version="${Number(v.id)}" tabindex="0" title="Select this version"><td><b>v${esc(v.version)}</b></td><td>${pill(v.status)}</td><td>${esc(v.source_format||'json').toUpperCase()}</td><td>${esc(v.updated_at||'—')}</td><td>${versionActions(v)}</td></tr>`;}
function marketCard(m){return `<article class="card mf-market-card"><header class="section-head"><div><span class="eyebrow">MARKET</span><h2>${esc(m.country_name||m.country_code)}</h2><div class="mini">${esc(m.country_code)} · ${esc(m.product_key)}</div></div><div>${pill(m.status)} ${pill(m.active_version_status||m.latest_version_status||'NO RELEASE')}</div></header><div class="mf-market-stats"><div><span>Active version</span><b>${esc(m.active_version||'—')}</b></div><div><span>Readiness</span><b>${(m.latest_readiness||m.active_readiness)?.score==null?'—':`${Number((m.latest_readiness||m.active_readiness).score)}%`}</b></div><div><span>Latest version</span><b>${esc(m.latest_version||m.active_version||'—')}</b></div><div><span>Onboarding</span><b>${esc(m.onboarding_mode||'—')}</b></div></div><div class="actions"><button class="btn primary" data-mf-open="${m.id}">OPEN MARKET</button>${m.status==='LIVE'?`<button class="btn danger" data-mf-status="${m.id}" data-status="SUSPENDED">SUSPEND</button><button class="btn muted" data-mf-status="${m.id}" data-status="RESTRICTED">RESTRICT</button>${m.onboarding_mode!=='OPEN'?`<button class="btn primary" data-mf-open-onboarding="${m.id}">OPEN ONBOARDING</button>`:''}`:''}${['SUSPENDED','RESTRICTED'].includes(m.status)?`<button class="btn primary" data-mf-status="${m.id}" data-status="LIVE">RESUME</button>`:''}${m.status!=='RETIRED'?`<button class="btn muted" data-mf-status="${m.id}" data-status="RETIRED">RETIRE</button>`:''}${m.status==='RETIRED'&&!m.active_version_id?`<button class="btn muted" data-mf-status="${m.id}" data-status="DRAFT">RESET TO DRAFT</button>`:''}</div></article>`;}
function bindWorkbenchActions(box,{api,ensureStepUp,loadWorkbench,refresh}){const stageButtons=[...box.querySelectorAll('[data-mf-stage]')];let activeStage=stageButtons[0]?.dataset.mfStage||'';const stageGroups=()=>[...box.querySelectorAll('[data-mf-task-category]')];const taskComplete=task=>String(task.querySelector('.mf-task-actions .pill')?.textContent||'').trim().toUpperCase().includes('COMPLETE');const updateGuidance=()=>{const allTasks=[...box.querySelectorAll('#mfLaunchWorkbench article.mf-task')];const remaining=allTasks.filter(task=>!taskComplete(task));const current=remaining.find(task=>!activeStage||task.closest('[data-mf-task-category]')?.dataset.mfTaskCategory===activeStage)||remaining[0];const label=box.querySelector('#mfLaunchNextSummary');if(label)label.textContent=current?`Next required task: ${String(current.querySelector('.mf-task-copy b')?.textContent||'Untitled task').trim()} · ${current.closest('[data-mf-task-category]')?.dataset.mfTaskCategory||'GENERAL'} · ${remaining.length} remaining`:'All displayed workbench tasks are marked complete. Run canonical readiness validation before publication.';const prev=box.querySelector('#mfPreviousStage'),next=box.querySelector('#mfNextStage');const idx=stageButtons.findIndex(b=>b.dataset.mfStage===activeStage);if(prev)prev.disabled=idx<=0;if(next)next.disabled=idx<0||idx>=stageButtons.length-1;};const showStage=(stage)=>{activeStage=stage||'';for(const group of stageGroups())group.hidden=Boolean(activeStage)&&group.dataset.mfTaskCategory!==activeStage;for(const button of stageButtons)button.setAttribute('aria-pressed',String(button.dataset.mfStage===activeStage));updateGuidance();};const moveStage=delta=>{const idx=stageButtons.findIndex(b=>b.dataset.mfStage===activeStage);const target=stageButtons[Math.max(0,Math.min(stageButtons.length-1,idx+delta))];if(target){showStage(target.dataset.mfStage);target.scrollIntoView({behavior:'smooth',block:'nearest'});}};stageButtons.forEach(button=>button.addEventListener('click',()=>showStage(button.dataset.mfStage)));if(stageButtons.length)showStage(stageButtons[0].dataset.mfStage);box.querySelector('#mfPreviousStage')?.addEventListener('click',()=>moveStage(-1));box.querySelector('#mfNextStage')?.addEventListener('click',()=>moveStage(1));box.querySelector('#mfShowAllStages')?.addEventListener('click',()=>showStage(''));box.querySelector('#mfDoNextTask')?.addEventListener('click',()=>{const allTasks=[...box.querySelectorAll('#mfLaunchWorkbench article.mf-task')];const next=allTasks.find(task=>!taskComplete(task));if(!next){const label=box.querySelector('#mfLaunchNextSummary');if(label)label.textContent='No incomplete tasks remain. Refresh canonical readiness and review any required approval before publication.';return;}const group=next.closest('[data-mf-task-category]');if(group)showStage(group.dataset.mfTaskCategory);const details=next.querySelector('details.mf-evidence-editor');if(details)details.open=true;next.scrollIntoView({behavior:'smooth',block:'center'});updateGuidance();});box.querySelector('#mfShowIncompleteTasks')?.addEventListener('click',event=>{const button=event.currentTarget;const filtering=button.dataset.filtering!=='true';button.dataset.filtering=String(filtering);for(const task of box.querySelectorAll('#mfLaunchWorkbench article.mf-task')){const complete=String(task.querySelector('.mf-task-actions .pill')?.textContent||'').trim().toUpperCase().includes('COMPLETE');task.hidden=filtering&&complete;}button.textContent=filtering?'SHOW ALL TASKS':'SHOW INCOMPLETE ONLY';});box.querySelectorAll('[data-mf-task-form]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const taskKey=form.dataset.taskKey,id=form.dataset.versionId,fd=new FormData(form),evidence={summary:String(fd.get('summary')||''),evidenceRef:String(fd.get('evidenceRef')||'')};if(taskKey.startsWith('legal:')){evidence.reviewer=String(fd.get('reviewer')||'');evidence.decision=String(fd.get('decision')||'');}const status=String(fd.get('status')||'IN_PROGRESS').toUpperCase();if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${id}/workbench/tasks/${taskKey}`))return;const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;try{await mutation(api,`/api/platform/admin/market-factory/versions/${id}/workbench/tasks/${taskKey}`,{status,evidence});await refresh();}catch(e){alert(`${e.code||'TASK_UPDATE_FAILED'}: ${e.message||'Unable to save task evidence.'}`);if(submit)submit.disabled=false;}}));box.querySelector('#mfRecoverPublication')?.addEventListener('click',async b=>{const id=b.currentTarget.dataset.versionId;if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${id}/recover-publication`))return;if(!confirm('Resume the recorded publication operation? This replays the idempotent reconciliation pipeline using the same launch/version identity. It does not activate the market. Inspect the recorded stage and current market state first.'))return;try{await mutation(api,`/api/platform/admin/market-factory/versions/${id}/recover-publication`);await refresh();}catch(e){alert(`${e.code||'PUBLICATION_RECOVERY_FAILED'}: ${e.message||'Controlled publication recovery did not complete.'}`)}});box.querySelector('#mfExportLaunchReport')?.addEventListener('click',async b=>{try{const r=await api(`/api/platform/admin/market-factory/versions/${b.currentTarget.dataset.versionId}/workbench`);downloadJson(`market-launch-report-${r.workbench.preview.country}-${r.workbench.version}.json`,r.workbench);}catch(e){alert(`${e.code||'REPORT_EXPORT_FAILED'}: ${e.message||'Unable to export the launch report.'}`)}});}

async function bindInlineResourcePreparation(box,{api,ensureStepUp,refresh}){const toggle=box.querySelector('#mfToggleInlineResource'),panel=box.querySelector('#mfInlineResourcePanel'),form=box.querySelector('#mfInlineResourceForm'),typeSelect=box.querySelector('#mfInlineResourceType'),result=box.querySelector('#mfInlineResourceResult');if(!toggle||!panel||!form||!typeSelect||!result)return;let pendingEntryId='';let definitions=[];const fieldHost=panel.querySelector('#mfTypedResourceFields');const advancedPanel=panel.querySelector('#mfAdvancedJsonPanel');const advancedToggle=panel.querySelector('#mfToggleAdvancedJson');const draftKey=()=>`onmission:market-launch:resource-draft:${typeSelect.value||'none'}`;const restoreDraft=()=>{try{const saved=JSON.parse(sessionStorage.getItem(draftKey())||'null');if(!saved)return;for(const field of panel.querySelectorAll('[data-mf-resource-field]')){if(Object.prototype.hasOwnProperty.call(saved,field.dataset.mfResourceField)){if(field.type==='checkbox')field.checked=Boolean(saved[field.dataset.mfResourceField]);else field.value=String(saved[field.dataset.mfResourceField]??'');}}const raw=form.querySelector('[name=payload]');if(raw&&saved.__advancedJson)raw.value=saved.__advancedJson;}catch{}};typeSelect.addEventListener('change',()=>{const selected=definitions.find(d=>String(d.entryType||d.type||d.code||'')===typeSelect.value)||{};if(fieldHost)fieldHost.innerHTML=renderTypedResourceFields(typeSelect.value,selected);restoreDraft();});advancedToggle?.addEventListener('click',()=>{if(!advancedPanel)return;advancedPanel.hidden=!advancedPanel.hidden;advancedToggle.setAttribute('aria-expanded',String(!advancedPanel.hidden));advancedToggle.textContent=advancedPanel.hidden?'ADVANCED JSON':'HIDE ADVANCED JSON';});panel.querySelector('#mfSaveLocalDraft')?.addEventListener('click',()=>{try{const data=readTypedResourceFields(panel);const raw=form.querySelector('[name=payload]');if(raw?.value.trim())data.__advancedJson=raw.value;sessionStorage.setItem(draftKey(),JSON.stringify(data));result.innerHTML='<div class="notice"><b>FORM DRAFT SAVED IN THIS BROWSER SESSION.</b><p class="mini">This is a local convenience draft, not a server-persisted market release or canonical resource.</p></div>';}catch(e){result.innerHTML=`<div class="notice danger">${esc(e.message)}</div>`;}});toggle.addEventListener('click',async()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));toggle.textContent=panel.hidden?'CREATE RESOURCE':'CLOSE RESOURCE FORM';if(panel.hidden||typeSelect.dataset.loaded==='true')return;try{const r=await api('/api/platform/admin/data-entry/definitions');const defs=arr(r.definitions);definitions=defs;typeSelect.innerHTML='<option value="">Select a governed resource type</option>'+defs.map(d=>`<option value="${esc(d.entryType||d.type||d.code||'')}">${esc(d.label||d.title||d.entryType||d.type||d.code||'Resource type')}</option>`).join('');typeSelect.dataset.loaded='true';if(!defs.length)typeSelect.innerHTML='<option value="">No resource types returned by the authority</option>';}catch(e){typeSelect.innerHTML='<option value="">Resource definitions unavailable</option>';result.innerHTML=`<div class="notice danger">${esc(e.code||'DATA_ENTRY_DEFINITIONS_UNAVAILABLE')}: ${esc(e.message||'Cannot load approved resource types. Retry after the authority is available.')}</div>`;}});form.addEventListener('submit',async event=>{event.preventDefault();pendingEntryId='';const fd=new FormData(form);let payload;try{const raw=String(fd.get('payload')||'').trim();const advancedOpen=advancedPanel&&!advancedPanel.hidden;if(advancedOpen&&raw){payload=JSON.parse(raw);}else{payload=readTypedResourceFields(panel);}if(!payload||Array.isArray(payload)||typeof payload!=='object'||!Object.keys(payload).length)throw new Error('Complete at least one resource field before previewing.');}catch(e){result.innerHTML=`<div class="notice danger">Invalid resource JSON: ${esc(e.message)}</div>`;return;}const entryType=String(fd.get('entryType')||'');if(!entryType){result.innerHTML='<div class="notice danger">Select a resource type before previewing.</div>';return;}const button=form.querySelector('button[type="submit"]');button.disabled=true;result.innerHTML='<div class="empty">Validating draft with the canonical Data Entry authority…</div>';try{const r=await api('/api/platform/admin/data-entry/preview',{method:'POST',headers:governedHeaders,body:{entryType,payload,purpose:String(fd.get('purpose')||'configuration'),sourceType:'super_admin',sourceId:'market-launch-workbench'}});if(!r.success||!r.entry?.entry_id)throw Object.assign(new Error('The authority did not return a valid previewed draft.'),{code:r.code||'DATA_ENTRY_PREVIEW_INVALID'});pendingEntryId=String(r.entry.entry_id);try{sessionStorage.removeItem(draftKey());}catch{}result.innerHTML=`<section class="notice"><b>GOVERNED DRAFT PREVIEWED</b><p>Entry ID: <code>${esc(pendingEntryId)}</code></p><p>Status: ${esc(r.entry.status||'PREVIEWED')} · Risk: ${esc(r.entry.risk_level||'UNASSESSED')}</p><p class="mini">This record is not automatically linked to the market package and is not published. Review it in Data Entry if the owning resource workflow requires additional steps.</p><button class="btn primary" type="button" id="mfCommitInlineResource">COMMIT DRAFT WITH STEP-UP</button></section>`;result.querySelector('#mfCommitInlineResource')?.addEventListener('click',async commitButton=>{if(!pendingEntryId)return;if(!await ensureStepUp(`POST:/api/platform/admin/data-entry/${pendingEntryId}/commit`))return;commitButton.currentTarget.disabled=true;try{const committed=await api(`/api/platform/admin/data-entry/${encodeURIComponent(pendingEntryId)}/commit`,{method:'POST',headers:governedHeaders,body:{}});result.innerHTML=`<section class="notice"><b>GOVERNED DATA ENTRY COMMITTED</b><p>Entry ID: <code>${esc(pendingEntryId)}</code></p><p>${esc(committed.entry?.status||committed.status||'Committed by the owning authority')}.</p><p class="mini">Market linkage and stage completion still require their own canonical operation and evidence. No launch gate was bypassed.</p><button class="btn muted" type="button" id="mfInlineResourceDone">RETURN TO LAUNCH STAGE</button></section>`;result.querySelector('#mfInlineResourceDone')?.addEventListener('click',()=>{panel.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.textContent='CREATE RESOURCE';refresh();});}catch(e){commitButton.currentTarget.disabled=false;result.insertAdjacentHTML('beforeend',`<div class="notice danger">${esc(e.code||'DATA_ENTRY_COMMIT_FAILED')}: ${esc(e.message||'Commit failed. The draft has not been assumed committed.')}</div>`);}});}catch(e){result.innerHTML=`<div class="notice danger">${esc(e.code||'DATA_ENTRY_PREVIEW_FAILED')}: ${esc(e.message||'Draft preview failed. No resource was assumed created.')}</div>`;}finally{button.disabled=false;}});}

function structuredPackageEditor(pkg,versionId){const legal=arr(pkg?.legal),content=arr(pkg?.content),languages=arr(pkg?.languages);return `<section class="card section mf-structured-editor"><header class="section-head"><div><span class="eyebrow">PACKAGE WORKSPACE</span><h2>Edit launch content and legal review status</h2><p class="sub">Change the fields you need here. Saving creates a new immutable package version; the current version remains preserved.</p></div><span class="pill neutral">v${esc(pkg?.metadata?.version||'—')}</span></header><form id="mfStructuredPackageForm" data-version-id="${versionId}"><section class="mf-task-group"><h3>LANGUAGE LABELS</h3>${languages.map((l,i)=>`<label class="mf-field"><span>${esc(l.code.toUpperCase())} · Canonical language display name</span><input class="input" name="language:${esc(l.code)}" data-mf-language-name="${esc(l.code)}" value="${esc(l.name)}" maxlength="100" required><small>Canonical language labels are reused globally. Match an existing label unless a separately governed canonical change is intended.</small></label>`).join('')}</section><section class="mf-task-group"><h3>SECTOR CONFIGURATION</h3>${arr(pkg?.sectors).map(item=>`<article class="mf-edit-item"><b>${esc(item.code)}</b><label class="mf-field"><span>Canonical sector name</span><input class="input" data-mf-sector-name="${esc(item.code)}" value="${esc(item.name)}" maxlength="180" required></label><label class="mf-field"><span>Description</span><textarea class="input" data-mf-sector-description="${esc(item.code)}" rows="3" maxlength="1000" required>${esc(item.description||'')}</textarea></label></article>`).join('')}</section><section class="mf-task-group"><h3>LEGAL APPLICABILITY REVIEW</h3>${legal.map(item=>`<article class="mf-edit-item"><div><b>${esc(item.title)}</b><p class="mini">${esc(item.description||'')}</p>${item.sourceUrl?`<a href="${esc(safeEvidenceUrl(item.sourceUrl))}" target="_blank" rel="noopener noreferrer">Open source</a>`:''}</div><label class="mf-field"><span>Review state</span><select class="input" data-mf-legal-status="${esc(item.key)}"><option value="researching" ${item.status==='researching'?'selected':''}>Researching</option><option value="prepared" ${item.status==='prepared'?'selected':''}>Prepared for review</option><option value="reviewed" ${item.status==='reviewed'?'selected':''}>Reviewed — evidence required</option><option value="missing" ${item.status==='missing'?'selected':''}>Missing / unresolved</option></select></label></article>`).join('')}</section><section class="mf-task-group"><h3>CUSTOMER-FACING CONTENT</h3>${content.map(item=>`<article class="mf-edit-item"><div><b>${esc(item.name)}</b><p class="mini">${esc(item.code)} · ${esc(item.languageCode.toUpperCase())} · ${esc(item.pageType)}</p></div><label class="mf-field"><span>Display name</span><input class="input" data-mf-content-name="${esc(item.code)}" value="${esc(item.name)}" maxlength="180" required></label><label class="mf-field"><span>Content body</span><textarea class="input" data-mf-content-body="${esc(item.code)}" rows="4" maxlength="30000" required>${esc(item.body)}</textarea></label><label class="mf-field"><span>Review state</span><select class="input" data-mf-content-status="${esc(item.code)}"><option value="draft" ${String(item.status).toLowerCase()==='draft'?'selected':''}>Draft</option><option value="validated" ${String(item.status).toLowerCase()==='validated'?'selected':''}>Validated — evidence required</option><option value="active" ${String(item.status).toLowerCase()==='active'?'selected':''}>Active — evidence required</option></select></label></article>`).join('')}</section><div class="actions"><button class="btn primary" type="submit">SAVE AS NEW PACKAGE VERSION</button><button class="btn muted" type="reset">RESET FORM</button></div><div id="mfStructuredPackageMsg"></div></form></section>`;}
function launchWorkbenchCard(w,certification=null){const tasks=arr(w.tasks);const groups={};for(const t of tasks)(groups[t.category||'GENERAL']??=[]).push(t);const pct=w.summary?.total?Math.round(100*w.summary.complete/w.summary.total):0;const guidedSteps=Object.entries(groups).map(([category,list],index)=>{const complete=list.filter(t=>String(t.status||'').toUpperCase()==='COMPLETE').length;const blocked=list.filter(t=>String(t.status||'').toUpperCase()==='BLOCKED').length;return `<button type="button" class="mf-guided-step" data-mf-stage="${esc(category)}" aria-pressed="${index===0?'true':'false'}"><span class="mf-guided-step-number">${index+1}</span><span class="mf-guided-step-copy"><b>${esc(category)}</b><small>${complete}/${list.length} evidenced${blocked?` · ${blocked} blocked`:''}</small></span><span class="mf-guided-step-state">${blocked?'BLOCKED':complete===list.length?'COMPLETE':'IN PROGRESS'}</span></button>`}).join('');return `<section class="mf-workbench-summary"><div class="mf-progress"><span style="width:${pct}%"></span></div><p class="mini">${w.summary?.complete||0} of ${w.summary?.total||0} tasks evidenced · ${w.summary?.blocked||0} gated · ${w.summary?.remaining||0} remaining</p>${certification?`<section class="notice ${certification.status==='COMPLETE'?'':certification.status==='BLOCKED'||certification.status==='WAITING_CANONICAL_AUTHORITY'?'danger':''}" aria-live="polite"><b>CONTROLLED LAUNCH SUPERVISOR · ${esc(certification.status)}</b><p>${esc(certification.nextAction?.title||certification.stopReason||'Refreshing canonical readiness is required.')}</p>${certification.nextAction?`<p class="mini">Owner: ${esc(certification.nextAction.owner)} · ${esc(certification.nextAction.mode)}</p>`:''}<p class="mini">${certification.counts?.VERIFIED||0} verified · ${certification.counts?.HUMAN_INPUT_REQUIRED||0} awaiting human input · ${certification.counts?.BLOCKED||0} blocked</p><button class="btn muted" id="mfRefreshCertification" data-version-id="${w.versionId}">REASSESS NEXT STEP</button></section>`:''}<section class="mf-guided-launch" aria-label="Guided market launch steps"><div class="section-head"><div><span class="eyebrow">GUIDED LAUNCH</span><h3>Complete the required work in order</h3><p class="sub">Steps are derived from canonical workbench task categories. Selecting a step filters the existing evidence tasks; it does not change readiness or bypass a gate.</p></div><span class="pill neutral">${Object.keys(groups).length} STAGES</span></div><nav class="mf-guided-step-list" aria-label="Launch stages">${guidedSteps}</nav><div class="mf-launch-next-summary" id="mfLaunchNextSummary" role="status" aria-live="polite">Finding the next required task from canonical workbench state…</div><section class="card section mf-inline-resource" aria-label="Create resource in launch workbench"><div class="section-head"><div><span class="eyebrow">IN-PLACE RESOURCE PREPARATION</span><h3>Create a missing resource without leaving Market Launch</h3><p class="sub">Prepare a governed Data Entry draft here, review the canonical preview, then commit with step-up authorization. This creates a governed data-entry record; it does not automatically link or publish a market resource.</p></div><button class="btn muted" type="button" id="mfToggleInlineResource" aria-expanded="false">CREATE RESOURCE</button></div><div id="mfInlineResourcePanel" hidden><form id="mfInlineResourceForm"><label class="mf-field"><span>Resource type</span><select class="input" name="entryType" id="mfInlineResourceType" required><option value="">Loading approved resource types…</option></select></label><label class="mf-field"><span>Purpose</span><select class="input" name="purpose"><option value="configuration">Market configuration</option><option value="content">Market content</option><option value="policy">Policy preparation</option></select></label><section class="mf-typed-resource-editor"><div class="section-head"><div><b>Resource details</b><p class="mini">Fields adapt to the selected resource definition. Required fields are marked. The canonical server remains the final validator.</p></div><button class="btn muted" type="button" id="mfToggleAdvancedJson" aria-expanded="false">ADVANCED JSON</button></div><div id="mfTypedResourceFields" class="mf-typed-resource-fields"><div class="empty">Select a resource type to load its fields.</div></div><div id="mfAdvancedJsonPanel" hidden><label class="mf-field"><span>Advanced resource payload (JSON)</span><textarea class="input" name="payload" rows="7" maxlength="20000" placeholder='{"name":"Example","code":"EXAMPLE"}'></textarea><small>Advanced mode is for resource types without a supported typed form. Never enter secrets.</small></label></div></section><div class="actions"><button class="btn muted" type="button" id="mfSaveLocalDraft">SAVE LOCAL FORM DRAFT</button><button class="btn primary" type="submit">VALIDATE & PREVIEW DRAFT</button></div></form><div id="mfInlineResourceResult" aria-live="polite"></div></div></section><div class="actions mf-task-navigation"><button class="btn muted" id="mfPreviousStage" type="button" disabled>PREVIOUS STAGE</button><button class="btn muted" id="mfNextStage" type="button">NEXT STAGE</button><button class="btn primary" id="mfDoNextTask" type="button">GO TO NEXT REQUIRED TASK</button><button class="btn muted" id="mfShowIncompleteTasks" data-filtering="false" type="button">SHOW INCOMPLETE ONLY</button><button class="btn muted" id="mfShowAllStages" type="button">SHOW ALL STAGES</button></div></section>${w.publicationOperation?`<div class="notice ${w.publicationOperation.status==='COMPLETED'?'':'danger'}"><b>PUBLICATION ${esc(w.publicationOperation.status)} · ${esc(w.publicationOperation.stage)}</b><p>${esc(w.publicationOperation.error_message||'Operation record retained for recovery and audit.')}</p>${['RECOVERY_REQUIRED','IN_PROGRESS'].includes(w.publicationOperation.status)?`<button class="btn danger" id="mfRecoverPublication" data-version-id="${w.versionId}">RESUME CONTROLLED RECOVERY</button>`:''}</div>`:''}${Object.entries(groups).map(([category,list])=>`<section class="mf-task-group" data-mf-task-category="${esc(category)}"><h3>${esc(category.toUpperCase())}</h3>${list.map(t=>`<article class="mf-task"><div class="mf-task-copy"><b>${esc(t.title)}</b><p class="mini">${esc(t.description)}</p>${t.gate?`<p class="notice danger mini">${esc(t.gate)}</p>`:''}${t.evidence?.summary?`<p class="mini">Evidence: ${esc(t.evidence.summary)} · <code>${esc(t.evidence.evidenceRef)}</code></p>`:''}</div><div class="mf-task-actions">${pill(t.status)}<details class="mf-evidence-editor"><summary>${t.status==='COMPLETE'?'Update evidence':'Record evidence'}</summary><form data-mf-task-form data-task-key="${esc(t.key)}" data-version-id="${w.versionId}"><label class="mf-field"><span>Summary</span><textarea class="input" name="summary" rows="3" minlength="10" required>${esc(t.evidence?.summary||'')}</textarea></label><label class="mf-field"><span>Evidence reference</span><input class="input" name="evidenceRef" value="${esc(t.evidence?.evidenceRef||'')}" placeholder="Report URL, test-run ID, document reference" required></label>${t.key.startsWith('legal:')?`<label class="mf-field"><span>Reviewer</span><input class="input" name="reviewer" value="${esc(t.evidence?.reviewer||'')}" required></label><label class="mf-field"><span>Decision</span><input class="input" name="decision" value="${esc(t.evidence?.decision||'')}" placeholder="Applicable / not applicable / further review required" required></label>`:''}<label class="mf-field"><span>Task status</span><select class="input" name="status"><option value="COMPLETE" ${t.status==='COMPLETE'?'selected':''}>Complete</option><option value="IN_PROGRESS" ${t.status==='IN_PROGRESS'?'selected':''}>In progress</option><option value="TODO" ${t.status==='TODO'?'selected':''}>Not started</option><option value="BLOCKED" ${t.status==='BLOCKED'?'selected':''}>Blocked</option></select></label><button class="btn primary" type="submit">SAVE EVIDENCE</button></form></details></div></article>`).join('')}</section>`).join('')}<div class="actions"><button class="btn muted" id="mfExportLaunchReport" data-version-id="${w.versionId}">EXPORT LAUNCH REPORT</button></div></section>`;}
function detail(m,render){const versions=arr(m.versions),selected=render.selectedVersionId?versions.find(v=>Number(v.id)===Number(render.selectedVersionId)):versions[0];return `<section class="card section"><header class="section-head"><div><span class="eyebrow">MARKET FACTORY · MARKET</span><h1>${esc(m.country_name||m.country_code)}</h1><p class="sub">${esc(m.country_code)} · ${esc(m.product_key)} · canonical market composition</p></div><div>${pill(m.status)}</div></header><div class="mf-market-stats"><div><span>Current release</span><b>${esc(m.active_version_id?versions.find(v=>Number(v.id)===Number(m.active_version_id))?.version||'—':'—')}</b></div><div><span>Versions</span><b>${versions.length}</b></div><div><span>Onboarding</span><b>${esc(m.onboarding_mode)}</b></div></div>${selected?`<section class="mf-selected"><header class="section-head"><div><span class="eyebrow">SELECTED PACKAGE</span><h2>v${esc(selected.version)}</h2></div>${pill(selected.status)}</header>${readinessCard(selected)}<section class="card section"><header class="section-head"><div><span class="eyebrow">LAUNCH WORKBENCH</span><h2>One guided launch workflow</h2><p class="sub">Evidence-backed tasks, operational gates and a release report for this immutable package version.</p></div><button class="btn muted" id="mfRefreshWorkbench" data-version-id="${Number(selected.id)}">REFRESH TASKS</button></header><div id="mfLaunchWorkbench"><div class="empty">Loading launch tasks…</div></div></section>${structuredPackageEditor(selected.package_json,Number(selected.id))}<details class="mf-package"><summary>ADVANCED · EDIT RAW PACKAGE JSON</summary><p class="sub">For advanced configuration only. Saving creates a new immutable version; the selected version is never overwritten.</p><textarea id="mfPackageEditor" class="input code-input" rows="18">${esc(jsonPretty(selected.package_json))}</textarea><div class="actions"><button class="btn muted" id="mfSaveRevision" data-version-id="${Number(selected.id)}">SAVE RAW JSON AS NEW VERSION</button></div><div id="mfRevisionMsg"></div></details><div class="actions"><button class="btn muted" id="mfPreviewReconciliation" data-version-id="${Number(selected.id)}">PREVIEW CANONICAL CHANGES</button></div><div id="mfReconciliationPreview"></div><details class="mf-package"><summary>INSPECT NORMALIZED PACKAGE</summary><pre class="code-input">${esc(jsonPretty(selected.package_json))}</pre></details>${versionActions(selected)}</section>`:'<div class="empty">No imported package version yet.</div>'}<section class="card section"><header class="section-head"><div><span class="eyebrow">RELEASE HISTORY</span><h2>Immutable market versions</h2></div></header><div class="table-wrap"><table class="table"><thead><tr><th>Version</th><th>Status</th><th>Source</th><th>Updated</th><th>Work</th></tr></thead><tbody>${versions.map(versionRow).join('')||'<tr><td colspan="5" class="empty">No versions.</td></tr>'}</tbody></table></div></section><div class="actions"><button class="btn muted" id="mfBack">BACK TO MARKETS</button><button class="btn" id="mfExportSelected" ${selected?'':'disabled'}>EXPORT SELECTED</button></div></section>`;}
export async function renderMarketFactory({api,state,ensureStepUp,show,esc:escapeFn}){
 const box=document.querySelector('#view-product-publisher');if(!box)return;state.marketFactory=state.marketFactory||{};box.innerHTML='<div class="empty">Loading Market Factory…</div>';
 const refresh=async()=>renderMarketFactory({api,state,ensureStepUp,show,esc:escapeFn});
 try{
  const data=await api('/api/platform/admin/market-factory');
  const markets=arr(data.markets);let opened=null;if(state.marketFactory.packageId){opened=await api(`/api/platform/admin/market-factory/${Number(state.marketFactory.packageId)}`);}
  if(opened?.market){box.innerHTML=detail(opened.market,state.marketFactory);const selectedForWorkbench=opened.market.versions.find(v=>Number(v.id)===Number(state.marketFactory.selectedVersionId))||opened.market.versions[0];const loadWorkbench=async()=>{if(!selectedForWorkbench)return;const target=box.querySelector('#mfLaunchWorkbench');if(!target)return;target.innerHTML='<div class="empty">Loading governed launch tasks…</div>';try{const [response,certResponse]=await Promise.all([api(`/api/platform/admin/market-factory/versions/${selectedForWorkbench.id}/workbench`),api(`/api/platform/admin/market-factory/versions/${selectedForWorkbench.id}/certification`)]);target.innerHTML=launchWorkbenchCard(response.workbench,certResponse.certification);bindWorkbenchActions(box,{api,ensureStepUp,loadWorkbench,refresh});bindInlineResourcePreparation(target,{api,ensureStepUp,refresh});target.querySelector('#mfRefreshCertification')?.addEventListener('click',loadWorkbench);}catch(e){target.innerHTML=`<div class="notice danger"><b>${esc(e.code||'WORKBENCH_UNAVAILABLE')}</b><p>${esc(e.message||'Unable to load launch tasks.')}</p></div>`;}};await loadWorkbench();box.querySelector('#mfRefreshWorkbench')?.addEventListener('click',loadWorkbench);box.querySelector('#mfStructuredPackageForm')?.addEventListener('submit',async event=>{event.preventDefault();try{if(!await ensureStepUp('POST:/api/platform/admin/market-factory/import'))return;const pkg=JSON.parse(JSON.stringify(selectedForWorkbench.package_json));box.querySelectorAll('[data-mf-language-name]').forEach(el=>{const item=pkg.languages.find(x=>x.code===el.dataset.mfLanguageName);if(item)item.name=el.value.trim();});box.querySelectorAll('[data-mf-sector-name]').forEach(el=>{const item=pkg.sectors.find(x=>x.code===el.dataset.mfSectorName);if(item)item.name=el.value.trim();});box.querySelectorAll('[data-mf-sector-description]').forEach(el=>{const item=pkg.sectors.find(x=>x.code===el.dataset.mfSectorDescription);if(item)item.description=el.value;});box.querySelectorAll('[data-mf-legal-status]').forEach(el=>{const item=pkg.legal.find(x=>x.key===el.dataset.mfLegalStatus);if(item)item.status=el.value;});box.querySelectorAll('[data-mf-content-name]').forEach(el=>{const item=pkg.content.find(x=>x.code===el.dataset.mfContentName);if(item)item.name=el.value.trim();});box.querySelectorAll('[data-mf-content-body]').forEach(el=>{const item=pkg.content.find(x=>x.code===el.dataset.mfContentBody);if(item)item.body=el.value;});box.querySelectorAll('[data-mf-content-status]').forEach(el=>{const item=pkg.content.find(x=>x.code===el.dataset.mfContentStatus);if(item)item.status=el.value;});if(pkg.metadata?.version===selectedForWorkbench.version){const parts=String(pkg.metadata.version).split('.').map(Number);parts[2]=(parts[2]||0)+1;pkg.metadata.version=parts.join('.');}const r=await api('/api/platform/admin/market-factory/import',{method:'POST',headers:governedHeaders,body:pkg});state.marketFactory.packageId=r.market?.id||opened.market.id;state.marketFactory.selectedVersionId=r.market?.versions?.[0]?.id||null;await refresh();}catch(e){const msg=box.querySelector('#mfStructuredPackageMsg');if(msg)msg.innerHTML=`<div class="notice danger"><b>${esc(e.code||'REVISION_FAILED')}</b><p>${esc(e.message||'Unable to save the new package version.')}</p></div>`;}});box.querySelector('#mfSaveRevision')?.addEventListener('click',async b=>{try{if(!await ensureStepUp('POST:/api/platform/admin/market-factory/import'))return;const editor=box.querySelector('#mfPackageEditor');const pkg=JSON.parse(editor.value);if(pkg.country?.iso!==selectedForWorkbench.package_json.country.iso||pkg.product?.productKey!==selectedForWorkbench.package_json.product.productKey)throw new Error('Country and product identity cannot change in a revision. Create a separate market package for a different identity.');if(pkg.metadata?.version===selectedForWorkbench.version){const parts=String(pkg.metadata.version).split('.').map(Number);parts[2]=(parts[2]||0)+1;pkg.metadata.version=parts.join('.');}const r=await api('/api/platform/admin/market-factory/import',{method:'POST',headers:governedHeaders,body:pkg});state.marketFactory.packageId=r.market?.id||opened.market.id;state.marketFactory.selectedVersionId=r.market?.versions?.[0]?.id||null;await refresh();}catch(e){const msg=box.querySelector('#mfRevisionMsg');if(msg)msg.innerHTML=`<div class="notice danger"><b>${esc(e.code||'REVISION_FAILED')}</b><p>${esc(e.message||'Unable to create package revision.')}</p></div>`;}});box.querySelectorAll('[data-mf-select-version]').forEach(row=>{const select=()=>{state.marketFactory.selectedVersionId=Number(row.dataset.mfSelectVersion);refresh()};row.addEventListener('click',e=>{if(!e.target.closest('button'))select()});row.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();select()}})});box.querySelector('#mfBack')?.addEventListener('click',()=>{state.marketFactory.packageId=null;refresh()});box.querySelector('#mfPreviewReconciliation')?.addEventListener('click',async b=>{const btn=b.currentTarget;btn.disabled=true;const target=box.querySelector('#mfReconciliationPreview');target.innerHTML='<div class="empty">Building read-only reconciliation preview…</div>';try{const r=await api(`/api/platform/admin/market-factory/versions/${btn.dataset.versionId}/reconciliation-preview`);target.innerHTML=reconciliationCard(r.preview);}catch(e){target.innerHTML=`<div class="notice danger"><b>${esc(e.code||'RECONCILIATION_PREVIEW_FAILED')}</b><p>${esc(e.message||'Unable to build reconciliation preview.')}</p></div>`;}finally{btn.disabled=false;}});box.querySelectorAll('[data-mf-validate]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${b.dataset.mfValidate}/validate`))return;await withError(async()=>{const result=await mutation(api,`/api/platform/admin/market-factory/versions/${b.dataset.mfValidate}/validate`);state.marketFactory.selectedVersionId=result.market?.versions?.[0]?.id||Number(b.dataset.mfValidate);await refresh()})}));box.querySelectorAll('[data-mf-authorize]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${b.dataset.mfAuthorize}/authorize`))return;await withError(async()=>{const result=await mutation(api,`/api/platform/admin/market-factory/versions/${b.dataset.mfAuthorize}/authorize`);state.marketFactory.selectedVersionId=result.market?.versions?.[0]?.id||Number(b.dataset.mfAuthorize);await refresh()})}));box.querySelectorAll('[data-mf-publish]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${b.dataset.mfPublish}/publish`))return;if(!confirm('Publish this release into PUBLISHED state? Canonical reconciliation will run, but the market will not become LIVE until a separate evidence-backed verification and activation step.'))return;await withError(async()=>{const result=await mutation(api,`/api/platform/admin/market-factory/versions/${b.dataset.mfPublish}/publish`);state.marketFactory.selectedVersionId=result.market?.active_version_id||Number(b.dataset.mfPublish);await refresh()})}));box.querySelectorAll('[data-mf-verify]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${b.dataset.mfVerify}/verify`))return;const summary=prompt('Release verification summary (include the checks run and result):');if(!summary)return;const evidenceRef=prompt('Verification evidence reference (test report, deployed runtime URL, run ID):');if(!evidenceRef)return;if(!confirm('Mark this PUBLISHED release VERIFIED? This does not activate the market or open onboarding.'))return;await withError(async()=>{const result=await mutation(api,`/api/platform/admin/market-factory/versions/${b.dataset.mfVerify}/verify`,{summary,evidenceRef});state.marketFactory.selectedVersionId=result.market?.versions?.[0]?.id||Number(b.dataset.mfVerify);await refresh()})}));box.querySelectorAll('[data-mf-activate]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/versions/${b.dataset.mfActivate}/activate`))return;if(!confirm('Activate this VERIFIED release? The market will be LIVE with INVITE_ONLY onboarding; customers will not be able to self-onboard.'))return;await withError(async()=>{const result=await mutation(api,`/api/platform/admin/market-factory/versions/${b.dataset.mfActivate}/activate`);state.marketFactory.selectedVersionId=result.market?.active_version_id||Number(b.dataset.mfActivate);await refresh()})}));box.querySelectorAll('[data-mf-export]').forEach(b=>b.addEventListener('click',async()=>{const r=await api(`/api/platform/admin/market-factory/export/${b.dataset.mfExport}`);downloadJson(r.export.filename,r.export.package)}));box.querySelector('#mfExportSelected')?.addEventListener('click',async()=>{const v=opened.market.versions.find(x=>Number(x.id)===Number(state.marketFactory.selectedVersionId))||opened.market.versions[0];if(!v)return;const r=await api(`/api/platform/admin/market-factory/export/${v.id}`);downloadJson(r.export.filename,r.export.package)});return;}
  box.innerHTML=`<div class="operating-surface mf-shell"><header class="control-hero"><div><span class="eyebrow">BUILD · MARKET FACTORY</span><h1 class="title">Market Factory</h1><p class="sub">Intake a complete market package, validate it, understand readiness, authorize it, and publish one governed market release. Canonical records are reconciled by identity; packages never become a second authority.</p></div><span class="pill ok">${esc(data.version)}</span></header><section class="card section mf-import"><header class="section-head"><div><span class="eyebrow">01 · INTAKE</span><h2>Import Market Package</h2><p class="sub">JSON paste, JSON file, or ZIP package. Import is staged and never writes live market truth.</p></div></header><textarea id="mfJson" class="input code-input" rows="12" placeholder='Paste a strict ON Mission market-package JSON here…'></textarea><div class="mf-file-row"><input id="mfFile" type="file" accept=".json,.zip,application/json,application/zip"><span class="mini">Maximum: 2 MB JSON / 8 MB ZIP · ZIP must contain market-package.json.</span></div><div class="actions"><button class="btn primary" id="mfImport">IMPORT PACKAGE</button><button class="btn muted" id="mfClear">CLEAR</button></div><div id="mfImportMsg"></div></section><section class="card section"><header class="section-head"><div><span class="eyebrow">02 · MARKETS</span><h2>Governed Markets</h2><p class="sub">One market package per product + country. Versions are immutable and replaced through the release pointer.</p></div><button class="btn muted" id="mfRefresh">REFRESH</button></header><div class="mf-market-grid">${markets.map(marketCard).join('')||'<div class="empty">No market packages have been imported yet.</div>'}</div></section><section class="card section"><header class="section-head"><div><span class="eyebrow">03 · GOVERNANCE</span><h2>Release rules</h2></div></header><div class="os-grid three"><article class="card"><b>NO DUPLICATES</b><p class="sub">Country, sector, policy and content identities are resolved by canonical code.</p></article><article class="card"><b>NO LIVE EDIT</b><p class="sub">Changes create a new market package version.</p></article><article class="card"><b>SAFE REPLACEMENT</b><p class="sub">Publication is staged; only a separately verified release can become active.</p></article></div></section></div>`;
  box.querySelector('#mfRefresh')?.addEventListener('click',refresh);box.querySelector('#mfClear')?.addEventListener('click',()=>{box.querySelector('#mfJson').value='';box.querySelector('#mfFile').value='';});box.querySelectorAll('[data-mf-open]').forEach(b=>b.addEventListener('click',()=>{state.marketFactory.packageId=Number(b.dataset.mfOpen);state.marketFactory.selectedVersionId=null;refresh()}));box.querySelectorAll('[data-mf-status]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp(`POST:/api/platform/admin/market-factory/${b.dataset.mfStatus}/status`))return;if(!confirm(`${b.dataset.status} this market? Existing history is retained.`))return;await withError(async()=>{await mutation(api,`/api/platform/admin/market-factory/${b.dataset.mfStatus}/status`,{status:b.dataset.status,onboardingMode:b.dataset.status==='LIVE'?'INVITE_ONLY':'CLOSED'});await refresh()})}));box.querySelectorAll('[data-mf-open-onboarding]').forEach(b=>b.addEventListener('click',async()=>{const scope=`POST:/api/platform/admin/market-factory/${b.dataset.mfOpenOnboarding}/status`;if(!await ensureStepUp(scope))return;if(!confirm('Open customer onboarding for this already-live market? Confirm legal, security, billing and pilot readiness have been approved.'))return;await withError(async()=>{await mutation(api,`/api/platform/admin/market-factory/${b.dataset.mfOpenOnboarding}/status`,{status:'LIVE',onboardingMode:'OPEN'});await refresh()})}));
  box.querySelector('#mfImport')?.addEventListener('click',async()=>{const msg=box.querySelector('#mfImportMsg');msg.innerHTML='';try{if(!await ensureStepUp('POST:/api/platform/admin/market-factory/import'))return;const file=box.querySelector('#mfFile')?.files?.[0];if(file&&file.size>(file.name.toLowerCase().endsWith('.zip')?8:2)*1024*1024)throw new Error(file.name.toLowerCase().endsWith('.zip')?'ZIP exceeds the 8 MB limit.':'JSON exceeds the 2 MB limit.');if(file&&!/\.(json|zip)$/i.test(file.name))throw new Error('Choose a .json or .zip package.');let body;if(file&&file.name.toLowerCase().endsWith('.zip')){const form=new FormData();form.append('file',file,file.name);body=form;}else if(file){body=JSON.parse(await file.text());}else body=JSON.parse(box.querySelector('#mfJson').value||'{}');const r=await api('/api/platform/admin/market-factory/import',{method:'POST',headers:governedHeaders,body});state.marketFactory.packageId=r.market?.id||null;state.marketFactory.selectedVersionId=r.market?.versions?.[0]?.id||null;msg.innerHTML='<div class="notice"><b>IMPORT STAGED.</b> No live canonical data was changed. Open the market to review readiness.</div>';await refresh();}catch(e){msg.innerHTML=`<div class="notice danger"><b>${esc(e.code||'IMPORT_FAILED')}</b><p>${esc(e.message||'Market package import failed. No live canonical data was changed.')}</p>${e.status?`<small>HTTP ${esc(e.status)}</small>`:''}</div>`;}});
 }catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">MARKET FACTORY</div><h2>Market Factory unavailable</h2><p class="sub">No market state was changed.</p><div class="notice danger">${esc(e.message||'Unable to read Market Factory.')}</div><button class="btn primary" id="mfRetry">RETRY</button></section>`;box.querySelector('#mfRetry')?.addEventListener('click',refresh);}
}
function downloadJson(filename,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
